package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
public class Fl01PlatformBlock extends BaseEntityBlock{
 public static final com.mojang.serialization.MapCodec<Fl01PlatformBlock> CODEC=simpleCodec(Fl01PlatformBlock::new);@Override protected com.mojang.serialization.MapCodec<? extends BaseEntityBlock>codec(){return CODEC;}
 public static final DirectionProperty FACING=BlockStateProperties.HORIZONTAL_FACING;public static final IntegerProperty PART=IntegerProperty.create("part",0,Fl01Geometry.PLATFORM.cells.length-1);public static final ThreadLocal<Boolean>MUTATING=ThreadLocal.withInitial(()->false);
 public Fl01PlatformBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(FACING,Direction.SOUTH).setValue(PART,0));}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(FACING,PART);}public static BlockPos root(BlockPos p,BlockState s){return Fl01Geometry.PLATFORM.root(p,s.getValue(FACING),s.getValue(PART));}
 @Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(FACING,Fl01PlatformItem.face(c.getPlayer(),c.getItemInHand()));}
 @Override public void setPlacedBy(Level l,BlockPos p,BlockState s,LivingEntity who,ItemStack item){if(!l.isClientSide&&who instanceof Player player&&l.getBlockEntity(p)instanceof Fl01PlatformBlockEntity b)b.placed(player);}
 public static InteractionResult interact(BlockState s,Level l,BlockPos pos,Player p,InteractionHand h){if(h!=InteractionHand.MAIN_HAND)return InteractionResult.PASS;if(l.isClientSide)return InteractionResult.SUCCESS;var root=root(pos,s);if(!l.hasChunkAt(root)||!(l.getBlockEntity(root)instanceof Fl01PlatformBlockEntity b))return InteractionResult.FAIL;var held=p.getItemInHand(h);if(SbwCompat.isMonitor(held)){PlatformMonitor.bind(b,p,held);return InteractionResult.CONSUME;}if(held.is(AddonItems.FL01.get()))b.loadDrone(p,held);else if(held.is(AddonItems.GASOLINE_JERRYCAN.get()))b.refuel(p,h);else if(p instanceof net.minecraft.server.level.ServerPlayer server)b.open(server);return InteractionResult.CONSUME;}
 @Override protected net.minecraft.world.ItemInteractionResult useItemOn(ItemStack stack,BlockState s,Level l,BlockPos p,Player who,InteractionHand h,BlockHitResult hit){interact(s,l,p,who,h);return net.minecraft.world.ItemInteractionResult.sidedSuccess(l.isClientSide);}
 @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player who,BlockHitResult hit){return interact(s,l,p,who,InteractionHand.MAIN_HAND);}
 @Override public BlockState playerWillDestroy(Level l,BlockPos p,BlockState s,Player who){if(!l.isClientSide&&who.getAbilities().instabuild&&s.getValue(PART)!=0)l.removeBlock(root(p,s),false);return super.playerWillDestroy(l,p,s,who);}
 @Override public void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){if(!l.isClientSide&&!s.is(next.getBlock())&&!MUTATING.get()){MUTATING.set(true);try{var root=root(p,s);if(l.getBlockEntity(root)instanceof Fl01PlatformBlockEntity b)b.dropContents();if(s.getValue(PART)!=0&&l.getBlockState(root).is(this))l.destroyBlock(root,true);for(int i=1;i<Fl01Geometry.PLATFORM.cells.length;i++){var at=Fl01Geometry.PLATFORM.cell(root,s.getValue(FACING),i);var part=l.getBlockState(at);if(part.is(this)&&part.getValue(PART)==i&&part.getValue(FACING)==s.getValue(FACING))l.removeBlock(at,false);}}finally{MUTATING.set(false);}}super.onRemove(s,l,p,next,moving);}
 @Override public void neighborChanged(BlockState s,Level l,BlockPos p,Block changed,BlockPos at,boolean moving){if(l.isClientSide||MUTATING.get()||!at.equals(p.below()))return;var root=root(p,s);for(var support:Fl01Geometry.PLATFORM.support)if(Fl01Geometry.offset(root,s.getValue(FACING),support).equals(p)&&!l.getBlockState(at).isFaceSturdy(l,at,Direction.UP)){l.destroyBlock(root,true);return;}}
 @Override public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return Fl01Geometry.PLATFORM.shape(s.getValue(FACING),s.getValue(PART));}@Override public VoxelShape getCollisionShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){if(c instanceof EntityCollisionContext ec&&ec.getEntity()instanceof Fl01Entity e&&e.ignores(p,s))return Shapes.empty();return getShape(s,l,p,c);}
 @Override public RenderShape getRenderShape(BlockState s){return RenderShape.INVISIBLE;}@Override public VoxelShape getOcclusionShape(BlockState s,BlockGetter l,BlockPos p){return Shapes.empty();}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return s.getValue(PART)==0?new Fl01PlatformBlockEntity(p,s):null;}@Override public <T extends BlockEntity>BlockEntityTicker<T>getTicker(Level l,BlockState s,BlockEntityType<T>t){return l.isClientSide?null:createTickerHelper(t,AddonBlockEntities.FL_LP.get(),Fl01PlatformBlockEntity::tick);}@Override public BlockState rotate(BlockState s,Rotation r){return s.setValue(FACING,r.rotate(s.getValue(FACING)));}@Override public BlockState mirror(BlockState s,Mirror m){return rotate(s,m.getRotation(s.getValue(FACING)));}
}
